import { randomUUID } from "node:crypto";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

export const IMAGE_TYPES: Record<string, string> = {
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/webp": "webp",
  "image/gif": "gif",
};

function env(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing env var ${name}`);
  return v;
}

// Works with any S3-compatible store (AWS S3, Cloudflare R2, MinIO) via S3_ENDPOINT.
let client: S3Client | undefined;
function s3() {
  client ??= new S3Client({
    region: process.env.S3_REGION ?? "auto",
    endpoint: process.env.S3_ENDPOINT || undefined,
    forcePathStyle: !!process.env.S3_ENDPOINT,
    credentials: {
      accessKeyId: env("S3_ACCESS_KEY_ID"),
      secretAccessKey: env("S3_SECRET_ACCESS_KEY"),
    },
  });
  return client;
}

export function publicUrlFor(key: string): string {
  return `${env("S3_PUBLIC_BASE_URL").replace(/\/$/, "")}/${key}`;
}

/** Keys are namespaced per user so a URL can be checked against its owner. */
export function userPrefix(userId: string): string {
  return publicUrlFor(`notes/${userId}/`);
}

/** Presigned PUT: the browser uploads straight to storage; type and size are signed. */
export async function createImageUpload(userId: string, contentType: string, size: number) {
  const key = `notes/${userId}/${randomUUID()}.${IMAGE_TYPES[contentType]}`;
  const uploadUrl = await getSignedUrl(
    s3(),
    new PutObjectCommand({
      Bucket: env("S3_BUCKET"),
      Key: key,
      ContentType: contentType,
      ContentLength: size,
    }),
    { expiresIn: 300 },
  );
  return { uploadUrl, url: publicUrlFor(key) };
}
EOF
