"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

async function json(res: Response) {
  const data = await res.json();
  if (!res.ok) throw new Error(data.error ?? "Request failed");
  return data;
}

export function NoteForm() {
  const router = useRouter();
  const [text, setText] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      const note = await json(
        await fetch("/api/notes", { method: "POST", body: JSON.stringify({ text }) }),
      );
      if (file) {
        const { uploadUrl, url } = await json(
          await fetch("/api/uploads", {
            method: "POST",
            body: JSON.stringify({ contentType: file.type, size: file.size }),
          }),
        );
        const put = await fetch(uploadUrl, {
          method: "PUT",
          headers: { "Content-Type": file.type },
          body: file,
        });
        if (!put.ok) throw new Error("Upload failed");
        await json(
          await fetch(`/api/notes/${note.id}/image`, { method: "PUT", body: JSON.stringify({ url }) }),
        );
      }
      setText("");
      setFile(null);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
      router.refresh();
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit} className="mt-2 space-y-2">
      <textarea
        value={text}
        onChange={(e) => setText(e.target.value)}
        required
        className="w-full rounded border p-2 text-sm"
        placeholder="Write a note…"
      />
      <input
        type="file"
        accept="image/jpeg,image/png,image/webp,image/gif"
        onChange={(e) => setFile(e.target.files?.[0] ?? null)}
        className="block text-sm"
      />
      <button disabled={busy} className="rounded border px-3 py-1 text-sm disabled:opacity-50">
        {busy ? "Saving…" : "Add note"}
      </button>
      {error && <p className="text-sm text-red-600">{error}</p>}
    </form>
  );
}
EOF
